package in.tucor.api.buyer;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/buyer/bank-accounts") public class BuyerAccountController{private final BuyerBankAccountRepository repo;public BuyerAccountController(BuyerBankAccountRepository r){repo=r;}public record Account(String id,String bankName,String accountType,String accountHolderName,String accountNumber,String ifsc,String branch,boolean verified,boolean primary){}public record Create(@NotBlank String bankName,@NotBlank String accountType,@NotBlank String accountHolderName,@NotBlank String accountNumber,@NotBlank String ifsc,String branch){}
@GetMapping public List<Account> all(Authentication a){return repo.findByBuyerIdOrderByCreatedAtAsc(UUID.fromString(a.getName())).stream().map(this::dto).toList();}@PostMapping public Account add(Authentication a,@Valid @RequestBody Create r){BuyerBankAccount x=new BuyerBankAccount();x.buyerId=UUID.fromString(a.getName());x.bankName=r.bankName();x.accountType=r.accountType();x.accountHolderName=r.accountHolderName();x.accountNumber=r.accountNumber();x.ifsc=r.ifsc();x.branch=r.branch();x.verified=false;x.primary=repo.findByBuyerIdOrderByCreatedAtAsc(x.buyerId).isEmpty();return dto(repo.save(x));}@DeleteMapping("/{id}") public void delete(Authentication a,@PathVariable UUID id){BuyerBankAccount x=repo.findById(id).orElseThrow();if(!x.buyerId.equals(UUID.fromString(a.getName())))throw new IllegalArgumentException("Account not found");repo.delete(x);}@PutMapping("/{id}/primary") public Account primary(Authentication a,@PathVariable UUID id){UUID uid=UUID.fromString(a.getName());List<BuyerBankAccount> all=repo.findByBuyerIdOrderByCreatedAtAsc(uid);BuyerBankAccount target=all.stream().filter(x->x.id.equals(id)).findFirst().orElseThrow();all.forEach(x->x.primary=x.id.equals(id));repo.saveAll(all);return dto(target);}private Account dto(BuyerBankAccount x){return new Account(x.id.toString(),x.bankName,x.accountType,x.accountHolderName,"•••• •••• "+x.accountNumber.substring(Math.max(0,x.accountNumber.length()-4)),x.ifsc,x.branch,x.verified,x.primary);}}